11	#ifndef TMRGSORT_HPP
12	#define TMRGSORT_HPP
13	
14	#include <pto/common/constants.hpp>
15	
16	namespace pto {
17	constexpr const int STRUCTSIZE = 8;
18	constexpr const int STRUCT_SIZE_SHIFT = 3;
19	constexpr const int COL_SIZE = 49152; // UBSIZE / ELEMSIZE = 192 * 1024 B / 4B
20	constexpr const int UB_SIZE = 196608; // 192*1024 B
21	constexpr const int BLOCK_NUM = 4;
22	constexpr const int ONE_ROW = 1;
23	constexpr const int EMPTY_LIST_SIZE = 0;
24	constexpr const int LIST_NUM_1 = 1;
25	constexpr const int LIST_NUM_2 = 2;
26	constexpr const int LIST_NUM_3 = 3;
27	constexpr const int LIST_NUM_4 = 4;
28	constexpr const int TMRGSORT_BLOCK_LEN = 64;
29	constexpr const int REPEAT_ONE_TIME = 1;
30	constexpr const int MAX_REPEAT_TIMES = 255;
31	
32	template <bool exhausted>
33	PTO_INTERNAL void GetExhaustedData(
34	    uint16_t& mrgSortList0, uint16_t& mrgSortList1, uint16_t& mrgSortList2, uint16_t& mrgSortList3)
35	{
36	    if constexpr (exhausted) {
37	        PtoSetWaitFlag<PIPE_V, PIPE_S>();
38	        int64_t mrgSortResult = get_vms4_sr();
39	        // VMS4_SR[15:0], number of finished region proposals in list0
40	        mrgSortList0 = static_cast<uint64_t>(mrgSortResult) & 0xFFFF;
41	        // VMS4_SR[31:16], number of finished region proposals in list1
42	        mrgSortList1 = (static_cast<uint64_t>(mrgSortResult) >> 16) & 0xFFFF;
43	        // VMS4_SR[47:32], number of finished region proposals in list2
44	        mrgSortList2 = (static_cast<uint64_t>(mrgSortResult) >> 32) & 0xFFFF;
45	        // VMS4_SR[63:48], number of finished region proposals in list3
46	        mrgSortList3 = (static_cast<uint64_t>(mrgSortResult) >> 48) & 0xFFFF;
47	    }
48	}
49	
50	template <bool exhausted>
51	PTO_INTERNAL uint64_t InitConfig()
52	{
53	    uint64_t config = uint64_t(REPEAT_ONE_TIME); // Xt[7:0]: repeat time
54	    if constexpr (exhausted) {
55	        config |= (uint64_t(0b1) << 12); // Xt[12]: 1-enable input list exhausted suspension
56	    } else {
57	        config |= (uint64_t(0b0) << 12); // Xt[12]: 0-disable input list exhausted suspension
58	    }
59	    return config;
60	}
61	
62	template <typename DstTileData>
63	PTO_INTERNAL void MovUb2Ub(
64	    __ubuf__ typename DstTileData::DType* dstPtr, __ubuf__ typename DstTileData::DType* tmpPtr, unsigned dstCol)
65	{
66	    pipe_barrier(PIPE_V);
67	    unsigned lenBurst = (dstCol * sizeof(typename DstTileData::DType) + BLOCK_BYTE_SIZE - 1) / BLOCK_BYTE_SIZE;
68	    pto_copy_ubuf_to_ubuf((__ubuf__ void*)dstPtr, (__ubuf__ void*)tmpPtr, 1, lenBurst, 0, 0);
69	}
70	
71	template <
72	    typename DstTileData, typename TmpTileData, typename Src0TileData, typename Src1TileData, typename Src2TileData,
73	    typename Src3TileData, bool exhausted, unsigned listNum>
74	__tf__ AICORE void TMrgsort(
75	    typename DstTileData::TileDType __out__ dst, typename TmpTileData::TileDType __out__ tmp,
76	    typename Src0TileData::TileDType __in__ src0, typename Src1TileData::TileDType __in__ src1,
77	    typename Src2TileData::TileDType __in__ src2, typename Src3TileData::TileDType __in__ src3, unsigned dstCol,
78	    uint16_t& mrgSortList0, uint16_t& mrgSortList1, uint16_t& mrgSortList2, uint16_t& mrgSortList3, unsigned src0Col,
79	    unsigned src1Col, unsigned src2Col, unsigned src3Col)
80	{
81	    __ubuf__ typename DstTileData::DType* dstPtr = (__ubuf__ typename DstTileData::DType*)__cce_get_tile_ptr(dst);
82	    __ubuf__ typename DstTileData::DType* tmpPtr = (__ubuf__ typename DstTileData::DType*)__cce_get_tile_ptr(tmp);
83	    __ubuf__ typename DstTileData::DType* src0Ptr = (__ubuf__ typename DstTileData::DType*)__cce_get_tile_ptr(src0);
84	    __ubuf__ typename DstTileData::DType* src1Ptr = (__ubuf__ typename DstTileData::DType*)__cce_get_tile_ptr(src1);
85	
86	    uint64_t config = InitConfig<exhausted>();
87	
88	    uint64_t count = uint64_t(src0Col); // VMS4_SR[15:0], number of finished region proposals in list0
89	    count |= (uint64_t(src1Col) << 16); // VMS4_SR[31:16], number of finished region proposals in list1
90	
91	    if constexpr (listNum == LIST_NUM_2) {
92	        config |= (uint64_t(0b0011) << 8); // Xt[11:8]: 4-bit mask signal
93	
94	        __ubuf__ typename DstTileData::DType* addrArray[LIST_NUM_2] = {
95	            (__ubuf__ typename DstTileData::DType*)(src0Ptr), (__ubuf__ typename DstTileData::DType*)(src1Ptr)};
96	
97	        vmrgsort4(tmpPtr, addrArray, count, config);
98	    } else if constexpr (listNum == LIST_NUM_3) {
99	        __ubuf__ typename DstTileData::DType* src2Ptr = (__ubuf__ typename DstTileData::DType*)__cce_get_tile_ptr(src2);
100	
101	        config |= (uint64_t(0b0111) << 8); // Xt[11:8]: 4-bit mask signal
102	
103	        count |= (uint64_t(src2Col) << 32); // VMS4_SR[47:32], number of finished region proposals in list2
104	
105	        __ubuf__ typename DstTileData::DType* addrArray[LIST_NUM_3] = {
106	            (__ubuf__ typename DstTileData::DType*)(src0Ptr), (__ubuf__ typename DstTileData::DType*)(src1Ptr),
107	            (__ubuf__ typename DstTileData::DType*)(src2Ptr)};
108	
109	        vmrgsort4(tmpPtr, addrArray, count, config);
110	    } else if constexpr (listNum == LIST_NUM_4) {
111	        __ubuf__ typename DstTileData::DType* src2Ptr = (__ubuf__ typename DstTileData::DType*)__cce_get_tile_ptr(src2);
112	        __ubuf__ typename DstTileData::DType* src3Ptr = (__ubuf__ typename DstTileData::DType*)__cce_get_tile_ptr(src3);
113	
114	        config |= (uint64_t(0b1111) << 8); // Xt[11:8]: 4-bit mask signal
115	
116	        count |= (uint64_t(src2Col) << 32); // VMS4_SR[47:32], number of finished region proposals in list2
117	        count |= (uint64_t(src3Col) << 48); // VMS4_SR[63:48], number of finished region proposals in list3
118	
119	        __ubuf__ typename DstTileData::DType* addrArray[LIST_NUM_4] = {
120	            (__ubuf__ typename DstTileData::DType*)(src0Ptr), (__ubuf__ typename DstTileData::DType*)(src1Ptr),
121	            (__ubuf__ typename DstTileData::DType*)(src2Ptr), (__ubuf__ typename DstTileData::DType*)(src3Ptr)};
122	
123	        vmrgsort4(tmpPtr, addrArray, count, config);
124	    }
125	
126	    GetExhaustedData<exhausted>(mrgSortList0, mrgSortList1, mrgSortList2, mrgSortList3);
127	    MovUb2Ub<DstTileData>(dstPtr, tmpPtr, dstCol);
128	}
129	
130	template <typename DstTileData, typename SrcTileData>
131	__tf__ AICORE void TMrgsort(
132	    typename DstTileData::TileDType __out__ dst, typename SrcTileData::TileDType __in__ src, uint32_t numStructures,
133	    uint8_t repeatTimes)
134	{
135	    __ubuf__ typename DstTileData::DType* dstPtr = (__ubuf__ typename DstTileData::DType*)__cce_get_tile_ptr(dst);
136	    __ubuf__ typename SrcTileData::DType* srcPtr = (__ubuf__ typename SrcTileData::DType*)__cce_get_tile_ptr(src);
137	
138	    uint64_t config = uint64_t(repeatTimes); // Xt[7:0]: repeat time
139	    config |= (uint64_t(0b1111) << 8);       // Xt[11:8]: 4-bit mask signal
140	    config |= (uint64_t(0b0) << 12);         // Xt[12]: 1-enable input list exhausted suspension
141	
142	    uint64_t count = (uint64_t(numStructures)); // VMS4_SR[15:0], length of block0 in the list
143	    count |= (uint64_t(numStructures) << 16);   // VMS4_SR[31:16], length of block1 in the list
144	    count |= (uint64_t(numStructures) << 32);   // VMS4_SR[47:32], length of block2 in the list
145	    count |= (uint64_t(numStructures) << 48);   // VMS4_SR[63:48], length of block3 in the list
146	
147	    constexpr const int BLOCK3_INDEX = 2;
148	    constexpr const int BLOCK4_INDEX = 3;
149	    unsigned offset = numStructures * STRUCTSIZE / sizeof(typename DstTileData::DType);
150	
151	    __ubuf__ typename SrcTileData::DType* addrArray[BLOCK_NUM] = {
152	        (__ubuf__ typename SrcTileData::DType*)(srcPtr), (__ubuf__ typename SrcTileData::DType*)(srcPtr + offset),
153	        (__ubuf__ typename SrcTileData::DType*)(srcPtr + offset * BLOCK3_INDEX),
154	        (__ubuf__ typename SrcTileData::DType*)(srcPtr + offset * BLOCK4_INDEX)};
155	    vmrgsort4(dstPtr, addrArray, count, config);
156	}
157	
158	template <
159	    typename DstTileData, typename TmpTileData, typename Src0TileData, typename Src1TileData, typename Src2TileData,
160	    typename Src3TileData, unsigned listNum>
161	PTO_INTERNAL void CheckOverMemory()
162	{
163	    constexpr size_t elemSize = sizeof(typename DstTileData::DType);
164	    constexpr size_t tmpSize = (listNum == LIST_NUM_1) ? DstTileData::Cols * elemSize : TmpTileData::Cols * elemSize;
165	    static_assert((tmpSize + Src0TileData::Cols * elemSize) <= UB_SIZE, "ERROR: memory usage exceeds UB limit!");
166	    if constexpr (listNum >= LIST_NUM_2) {
167	        static_assert(Src1TileData::Cols * elemSize <= UB_SIZE, "ERROR: src1 memory usage exceeds UB limit!");
168	    }
169	    if constexpr (listNum >= LIST_NUM_3) {
170	        static_assert(Src2TileData::Cols * elemSize <= UB_SIZE, "ERROR: src2 memory usage exceeds UB limit!");
171	    }
172	    if constexpr (listNum >= LIST_NUM_4) {
173	        static_assert(Src3TileData::Cols * elemSize <= UB_SIZE, "ERROR: src3 memory usage exceeds UB limit!");
174	    }
175	}
176	
177	template <
178	    typename DstTileData, typename TmpTileData, typename Src0TileData, typename Src1TileData, typename Src2TileData,
179	    typename Src3TileData>
180	PTO_INTERNAL void CheckStatic()
181	{
182	    using DstType = typename DstTileData::DType;
183	    static_assert(
184	        (std::is_same<DstType, half>::value) || (std::is_same<DstType, float>::value),
185	        "TMrgsort: Unsupported data type! Supported types is half/float");
186	    static_assert(
187	        (std::is_same<DstType, typename TmpTileData::DType>::value) &&
188	            (std::is_same<DstType, typename Src0TileData::DType>::value) &&
189	            (std::is_same<DstType, typename Src1TileData::DType>::value) &&
190	            (std::is_same<DstType, typename Src2TileData::DType>::value) &&
191	            (std::is_same<DstType, typename Src3TileData::DType>::value),
192	        "TMrgsort: Destination and Source tile data types must be the same.");
193	    static_assert(
194	        (DstTileData::Loc == TileType::Vec) && (TmpTileData::Loc == TileType::Vec) &&
195	            (Src0TileData::Loc == TileType::Vec) && (Src1TileData::Loc == TileType::Vec) &&
196	            (Src2TileData::Loc == TileType::Vec) && (Src3TileData::Loc == TileType::Vec),
197	        "TMrgsort: the TileType of Destination and Source tile must be Vec.");
198	    static_assert(
199	        (DstTileData::Rows == ONE_ROW) && (TmpTileData::Rows == ONE_ROW) && (Src0TileData::Rows == ONE_ROW) &&
200	            (Src1TileData::Rows == ONE_ROW) && (Src2TileData::Rows == ONE_ROW),
201	        "TMrgsort: the row of Destination and Source tile must be 1.");
202	    static_assert(
203	        (DstTileData::isRowMajor && TmpTileData::isRowMajor && Src0TileData::isRowMajor && Src1TileData::isRowMajor &&
204	         Src2TileData::isRowMajor && Src3TileData::isRowMajor),
205	        "TMrgsort: the BLayout of Destination and Source tile must be RowMajor.");
206	}
207	
208	template <
209	    typename DstTileData, typename TmpTileData, typename Src0TileData, typename Src1TileData, typename Src2TileData,
210	    typename Src3TileData, bool exhausted>
211	PTO_INTERNAL void TMRGSORT_IMPL(
212	    DstTileData& dst, MrgSortExecutedNumList& executedNumList, TmpTileData& tmp, Src0TileData& src0, Src1TileData& src1,
213	    Src2TileData& src2, Src3TileData& src3)
214	{
215	    CheckStatic<DstTileData, TmpTileData, Src0TileData, Src1TileData, Src2TileData, Src3TileData>();
216	    CheckOverMemory<DstTileData, TmpTileData, Src0TileData, Src1TileData, Src2TileData, Src3TileData, LIST_NUM_4>();
217	    unsigned dstCol = dst.GetValidCol();
218	    PTO_ASSERT(
219	        (src0.GetValidCol() + src1.GetValidCol() + src2.GetValidCol() + src3.GetValidCol() + tmp.GetValidCol()) *
220	                sizeof(typename DstTileData::DType) <
221	            UB_SIZE,
222	        "ERROR: Total memory usage exceeds UB limit!");
223	    constexpr unsigned ELE_NUM_SHIFT = (std::is_same<typename DstTileData::DType, float>::value) ? 1 : 2;
224	    unsigned src0Col = src0.GetValidCol() >> ELE_NUM_SHIFT;
225	    unsigned src1Col = src1.GetValidCol() >> ELE_NUM_SHIFT;
226	    unsigned src2Col = src2.GetValidCol() >> ELE_NUM_SHIFT;
227	    unsigned src3Col = src3.GetValidCol() >> ELE_NUM_SHIFT;
228	    TMrgsort<DstTileData, TmpTileData, Src0TileData, Src1TileData, Src2TileData, Src3TileData, exhausted, LIST_NUM_4>(
229	        dst.data(), tmp.data(), src0.data(), src1.data(), src2.data(), src3.data(), dstCol,
230	        executedNumList.mrgSortList0, executedNumList.mrgSortList1, executedNumList.mrgSortList2,
231	        executedNumList.mrgSortList3, src0Col, src1Col, src2Col, src3Col);
232	}
233	
234	template <
235	    typename DstTileData, typename TmpTileData, typename Src0TileData, typename Src1TileData, typename Src2TileData,
236	    bool exhausted>
237	PTO_INTERNAL void TMRGSORT_IMPL(
238	    DstTileData& dst, MrgSortExecutedNumList& executedNumList, TmpTileData& tmp, Src0TileData& src0, Src1TileData& src1,
239	    Src2TileData& src2)
240	{
241	    CheckStatic<DstTileData, TmpTileData, Src0TileData, Src1TileData, Src2TileData, Src0TileData>();
242	    CheckOverMemory<DstTileData, TmpTileData, Src0TileData, Src1TileData, Src2TileData, Src0TileData, LIST_NUM_3>();
243	    unsigned dstCol = dst.GetValidCol();
244	    PTO_ASSERT(
245	        (src0.GetValidCol() + src1.GetValidCol() + src2.GetValidCol() + tmp.GetValidCol()) *
246	                sizeof(typename DstTileData::DType) <
247	            UB_SIZE,
248	        "ERROR: Total memory usage exceeds UB limit!");
249	    constexpr unsigned ELE_NUM_SHIFT = (std::is_same<typename DstTileData::DType, float>::value) ? 1 : 2;
250	    unsigned src0Col = src0.GetValidCol() >> ELE_NUM_SHIFT;
251	    unsigned src1Col = src1.GetValidCol() >> ELE_NUM_SHIFT;
252	    unsigned src2Col = src2.GetValidCol() >> ELE_NUM_SHIFT;
253	    TMrgsort<DstTileData, TmpTileData, Src0TileData, Src1TileData, Src2TileData, Src2TileData, exhausted, LIST_NUM_3>(
254	        dst.data(), tmp.data(), src0.data(), src1.data(), src2.data(), src2.data(), dstCol,
255	        executedNumList.mrgSortList0, executedNumList.mrgSortList1, executedNumList.mrgSortList2,
256	        executedNumList.mrgSortList3, src0Col, src1Col, src2Col, EMPTY_LIST_SIZE);
257	}
258	
259	template <typename DstTileData, typename TmpTileData, typename Src0TileData, typename Src1TileData, bool exhausted>
260	PTO_INTERNAL void TMRGSORT_IMPL(
261	    DstTileData& dst, MrgSortExecutedNumList& executedNumList, TmpTileData& tmp, Src0TileData& src0, Src1TileData& src1)
262	{
263	    CheckStatic<DstTileData, TmpTileData, Src0TileData, Src1TileData, Src0TileData, Src0TileData>();
264	    CheckOverMemory<DstTileData, TmpTileData, Src0TileData, Src1TileData, Src0TileData, Src0TileData, LIST_NUM_2>();
265	    unsigned dstCol = dst.GetValidCol();
266	    PTO_ASSERT(
267	        (src0.GetValidCol() + src1.GetValidCol() + tmp.GetValidCol()) * sizeof(typename DstTileData::DType) < UB_SIZE,
268	        "ERROR: Total memory usage exceeds UB limit!");
269	    constexpr unsigned ELE_NUM_SHIFT = (std::is_same<typename DstTileData::DType, float>::value) ? 1 : 2;
270	    unsigned src0Col = src0.GetValidCol() >> ELE_NUM_SHIFT;
271	    unsigned src1Col = src1.GetValidCol() >> ELE_NUM_SHIFT;
272	    TMrgsort<DstTileData, TmpTileData, Src0TileData, Src1TileData, Src1TileData, Src1TileData, exhausted, LIST_NUM_2>(
273	        dst.data(), tmp.data(), src0.data(), src1.data(), src1.data(), src1.data(), dstCol,
274	        executedNumList.mrgSortList0, executedNumList.mrgSortList1, executedNumList.mrgSortList2,
275	        executedNumList.mrgSortList3, src0Col, src1Col, EMPTY_LIST_SIZE, EMPTY_LIST_SIZE);
276	}
277	
278	// The blockLen size includes values and indexes, such as 32 values and indexes: blockLen=64
279	template <typename DstTileData, typename SrcTileData>
280	PTO_INTERNAL void TMRGSORT_IMPL(DstTileData& dst, SrcTileData& src, uint32_t blockLen)
281	{
282	    CheckStatic<DstTileData, DstTileData, SrcTileData, SrcTileData, SrcTileData, SrcTileData>();
283	    CheckOverMemory<DstTileData, DstTileData, SrcTileData, SrcTileData, SrcTileData, SrcTileData, LIST_NUM_1>();
284	    uint32_t dstCol = dst.GetValidCol();
285	    uint32_t srcCol = src.GetValidCol();
286	    PTO_ASSERT(
287	        (srcCol + dstCol) * sizeof(typename DstTileData::DType) < UB_SIZE,
288	        "ERROR: Total memory usage exceeds UB limit!");
289	    // A struct is 8 bytes
290	    uint32_t numStructures = blockLen * sizeof(typename SrcTileData::DType) >> STRUCT_SIZE_SHIFT;
291	    PTO_ASSERT(blockLen % TMRGSORT_BLOCK_LEN == 0, "blockLen is a multiple of 64");
292	    PTO_ASSERT(
293	        srcCol % (blockLen * BLOCK_NUM) == 0,
294	        "ERROR: The input Tile Valid size requirement is an integer multiple of blockLen * 4.");
295	    uint8_t repeatTimes = srcCol / (blockLen * BLOCK_NUM);
296	    PTO_ASSERT(
297	        repeatTimes >= REPEAT_ONE_TIME && repeatTimes <= MAX_REPEAT_TIMES,
298	        "ERROR: The range of Tile Valid divided by blockLen is [1,255].");
299	    TMrgsort<DstTileData, SrcTileData>(dst.data(), src.data(), numStructures, repeatTimes);
300	}
301	
302	template <typename Src0TileData, typename Src1TileData, typename Src2TileData, typename Src3TileData>
303	PTO_INTERNAL constexpr uint32_t GETMRGSORTTMPSIZE()
304	{
305	    return Src0TileData::Cols + Src1TileData::Cols + Src2TileData::Cols + Src3TileData::Cols;
306	}
307	
308	template <typename Src0TileData, typename Src1TileData, typename Src2TileData>
309	PTO_INTERNAL constexpr uint32_t GETMRGSORTTMPSIZE()
310	{
311	    return Src0TileData::Cols + Src1TileData::Cols + Src2TileData::Cols;
312	}
313	
314	template <typename Src0TileData, typename Src1TileData>
315	PTO_INTERNAL constexpr uint32_t GETMRGSORTTMPSIZE()
316	{
317	    return Src0TileData::Cols + Src1TileData::Cols;
318	}
319	} // namespace pto
320	#endif
