18	template <int Cols>
19	PTO_INTERNAL int32_t FillMrgArray(int32_t* mrgArray, int blockLen)
20	{
21	    int32_t arrayCount = 0;
22	    int32_t tmpInner = Cols;
23	    for (int32_t i = blockLen; i >= 64; i /= 4) {
24	        int32_t count;
25	        for (count = 0; count < tmpInner / i; count++) {
26	            mrgArray[arrayCount++] = i;
27	        }
28	        tmpInner -= count * i;
29	    }
30	    return arrayCount;
31	}
