33	template <
34	    typename T, int gShape0, int gShape1, int gShape2, int gShape3, int gShape4, int gWholeShape0, int gWholeShape1,
35	    int gWholeShape2, int gWholeShape3, int gWholeShape4, int topk, int blockDim>
36	AICORE inline void Check()
37	{
38	    constexpr int totalRow = gShape0 * gShape1 * gShape2 * gShape3;
39	    constexpr int validRow = gShape0 * gShape1 * gShape2 * gShape3 / blockDim;
40	    constexpr int validCol = gShape4;
41	    constexpr int TYPE_COEF = sizeof(float) / sizeof(T);
42	    constexpr int dstCols = validCol * 2 * TYPE_COEF;
43	    constexpr uint32_t sort32DstSize = SINGLE_LOOP_ROW * dstCols * sizeof(T) * 2;
44	    constexpr uint32_t srcSize = SINGLE_LOOP_ROW * validCol * sizeof(T) * 2;
45	
46	    static_assert(totalRow % blockDim == 0, "expect totalRow % blockDim == 0");
47	    static_assert(sort32DstSize * 3 + validCol * sizeof(uint32_t) * 5 + srcSize < 192 * 1024, "memory is exhausted.");
48	    static_assert(validRow % (SINGLE_LOOP_ROW * 2) == 0, "expect validRow % (SINGLE_LOOP_ROW * 2) == 0.");
49	}
