51	template <typename DstTileData, typename SrcTileData, typename TmpTileData, typename T, int Cols, int topk>
52	PTO_INTERNAL void SortTailBlock(DstTileData& dstTile, SrcTileData& srcTile, int blockLen, uint64_t tmpAddr)
53	{
54	    TmpTileData tmp1Tile(1, Cols);
55	    TASSIGN(tmp1Tile, tmpAddr);
56	
57	    int32_t mrgArray[15] = {0};
58	    int32_t arrayCount = FillMrgArray<Cols>(mrgArray, blockLen);
59	    uint16_t mrgSortedLen = 0;
60	    MrgSortExecutedNumList executedNumList;
61	    for (int32_t i = 0; i < arrayCount - 1; ++i) {
62	        mrgSortedLen += static_cast<uint16_t>(mrgArray[i]);
63	        uint64_t tmpMrgSortedLen = mrgSortedLen;
64	        uint64_t tmpMrgArray = mrgArray[i + 1];
65	        if (tmpMrgSortedLen > topk) {
66	            tmpMrgSortedLen = topk;
67	        }
68	        if (tmpMrgArray > topk) {
69	            tmpMrgArray = topk;
70	        }
71	
72	        SrcTileData src0Tile(1, tmpMrgSortedLen);
73	        SrcTileData src1Tile(1, tmpMrgArray);
74	        SrcTileData curDstTile(1, tmpMrgSortedLen + tmpMrgArray);
75	        TASSIGN(src0Tile, (uint64_t)srcTile.data());
76	        TASSIGN(src1Tile, (uint64_t)srcTile.data() + mrgSortedLen * sizeof(T));
77	        TASSIGN(curDstTile, (uint64_t)srcTile.data());
78	        TMRGSORT<DstTileData, TmpTileData, SrcTileData, SrcTileData, 0>(
79	            curDstTile, executedNumList, tmp1Tile, src0Tile, src1Tile);
80	        pipe_barrier(PIPE_V);
81	    }
82	}
