84	template <typename DstTileData, typename SrcTileData, int kTRows_, int kTCols_, int valid_row, int valid_col, int dtopk>
85	PTO_INTERNAL void MrgsortSingleRow(DstTileData& dstTile, SrcTileData& srcTile, uint64_t tmpAddr)
86	{
87	    using T = typename SrcTileData::DType;
88	    constexpr uint32_t TYPE_COEF = sizeof(float) / sizeof(T);
89	    uint32_t blockLen = 64 * TYPE_COEF;
90	
91	    // Merge sort data for every 4 blockLen lengths.
92	    for (; blockLen * 4 <= valid_col; blockLen *= 4) {
93	        uint16_t cols = valid_col / (blockLen * 4) * (blockLen * 4);
94	        SrcTileData srcSortedTile(1, cols);
95	        SrcTileData tmpSortedTile(1, cols);
96	        TASSIGN(srcSortedTile, (uint64_t)srcTile.data());
97	        TASSIGN(tmpSortedTile, tmpAddr);
98	        TMRGSORT<SrcTileData, SrcTileData>(tmpSortedTile, srcSortedTile, blockLen);
99	        pipe_barrier(PIPE_V);
100	        TMOV(srcSortedTile, tmpSortedTile);
101	        pipe_barrier(PIPE_V);
102	    }
103	
104	    // sort tail block
105	    if (blockLen < valid_col) {
106	        SortTailBlock<DstTileData, SrcTileData, SrcTileData, T, valid_col, dtopk>(srcTile, srcTile, blockLen, tmpAddr);
107	        SrcTileData tmpMovTile(1, dtopk);
108	        TASSIGN(tmpMovTile, (uint64_t)srcTile.data());
109	        pipe_barrier(PIPE_V);
110	        TMOV(dstTile, tmpMovTile);
111	    } else {
112	        SrcTileData tmpMovTile(1, dtopk);
113	        TASSIGN(tmpMovTile, (uint64_t)srcTile.data());
114	        pipe_barrier(PIPE_V);
115	        TMOV(dstTile, tmpMovTile);
116	    }
117	}
