152	template <typename T, typename DstTileData, typename SrcTileData, typename RowTile, bool isIndex>
153	PTO_INTERNAL void ExtractDataOrIndex(DstTileData& dstTile, SrcTileData& srcTile)
154	{
155	    for (size_t i = 0; i < srcTile.GetValidRow(); ++i) {
156	        RowTile rowTile(1, srcTile.GetValidCol());
157	        TASSIGN(rowTile, (uint64_t)srcTile.data() + i * SrcTileData::Cols * sizeof(T));
158	        if constexpr (isIndex == false) {
159	            RowTile rowDTile(1, dstTile.GetValidCol());
160	            TASSIGN(rowDTile, (uint64_t)dstTile.data() + i * DstTileData::Cols * sizeof(T));
161	            if constexpr (std::is_same_v<T, half>) {
162	                TGATHER<RowTile, RowTile, MaskPattern::P0001>(rowDTile, rowTile);
163	            } else {
164	                TGATHER<RowTile, RowTile, MaskPattern::P0101>(rowDTile, rowTile);
165	            }
166	        } else {
167	            using indexT = uint32_t;
168	            using CopySrcTileData = Tile<TileType::Vec, indexT, 1, DstTileData::Cols * 2, BLayout::RowMajor, -1, -1>;
169	            CopySrcTileData copyTile(1, dstTile.GetValidCol() * 2);
170	            TASSIGN(copyTile, (uint64_t)rowTile.data());
171	
172	            using IndexRowTileData = Tile<TileType::Vec, indexT, 1, DstTileData::Cols, BLayout::RowMajor, -1, -1>;
173	            IndexRowTileData rowITile(1, dstTile.GetValidCol());
174	            TASSIGN(rowITile, (uint64_t)dstTile.data() + i * DstTileData::Cols * sizeof(indexT));
175	
176	            TGATHER<IndexRowTileData, CopySrcTileData, MaskPattern::P1010>(rowITile, copyTile);
177	        }
178	    }
179	}
180	
181	template <
182	    typename T, typename GlobalData, typename DstDataGlobalData, typename DstIdxGlobalData, typename DstTileData,
183	    typename DstDataTileData, typename DstIndexTileData, typename SrcTileData, typename IndexTileData,
184	    int SINGLE_LOOP_ROW, int dstCols, int validCol, int topk>
185	AICORE inline void ProcessSingleRow(
186	    int cur, GlobalData& srcGlobal, DstDataGlobalData& dstDataGlobal, DstIdxGlobalData& dstIdxGlobal,
187	    DstTileData* sort32DstTile, SrcTileData* srcTile, IndexTileData& indexTile, DstTileData* mrgDstTile,
188	    DstDataTileData* dTile, DstIndexTileData* iTile, uint64_t tmpAddr, event_t loadEvent, event_t storeEvent)
189	{
190	    constexpr int TYPE_COEF = sizeof(float) / sizeof(T);
191	    using SingleRowTileData = Tile<TileType::Vec, T, 1, dstCols, BLayout::RowMajor, -1, -1>;
192	    wait_flag(PIPE_V, PIPE_MTE2, loadEvent);
193	
194	    TLOAD(srcTile[cur], srcGlobal);
195	    set_flag(PIPE_MTE2, PIPE_V, (event_t)cur);
196	    wait_flag(PIPE_MTE2, PIPE_V, (event_t)cur);
197	
198	    SortEachGroup<
199	        T, DstTileData, SrcTileData, IndexTileData, SingleRowTileData, SINGLE_LOOP_ROW, validCol, SINGLE_LOOP_ROW,
200	        validCol>(sort32DstTile[cur], srcTile[cur], indexTile);
201	
202	    set_flag(PIPE_V, PIPE_MTE2, loadEvent);
203	
204	    pipe_barrier(PIPE_V);
205	    MrgsortSingleTile<
206	        T, DstTileData, DstTileData, SingleRowTileData, SINGLE_LOOP_ROW, dstCols, SINGLE_LOOP_ROW, dstCols,
207	        topk * 2 * TYPE_COEF>(mrgDstTile[cur], sort32DstTile[cur], tmpAddr);
208	
209	    pipe_barrier(PIPE_V);
210	    ExtractDataOrIndex<T, DstDataTileData, DstTileData, SingleRowTileData, 0>(dTile[cur], mrgDstTile[cur]);
211	    set_flag(PIPE_V, PIPE_MTE3, storeEvent);
212	
213	    pipe_barrier(PIPE_V);
214	    ExtractDataOrIndex<T, DstIndexTileData, DstTileData, SingleRowTileData, 1>(iTile[cur], mrgDstTile[cur]);
215	    set_flag(PIPE_V, PIPE_MTE3, (event_t)(storeEvent + 2));
216	    wait_flag(PIPE_V, PIPE_MTE3, storeEvent);
217	
218	    TSTORE(dstDataGlobal, dTile[cur]);
219	    wait_flag(PIPE_V, PIPE_MTE3, (event_t)(storeEvent + 2));
220	    TSTORE(dstIdxGlobal, iTile[cur]);
221	}
222	
223	template <
224	    typename T, typename GlobalData, typename DstDataGlobalData, typename DstIdxGlobalData, typename DstTileData,
225	    typename DstDataTileData, typename DstIndexTileData, typename SrcTileData, typename IndexTileData, int dstCols,
226	    int Cols, int validCol, int topk>
227	AICORE inline void ProcessIteration(
228	    __gm__ T* out, __gm__ T* src, __gm__ uint32_t* index, uint32_t i, uint64_t tmpAddr, uint64_t nextTmpAddr,
229	    DstTileData sort32DstTile[BUFFER_NUM], SrcTileData srcTile[BUFFER_NUM], IndexTileData indexTile,
230	    DstTileData mrgDstTile[BUFFER_NUM], DstDataTileData dTile[BUFFER_NUM], DstIndexTileData iTile[BUFFER_NUM])
231	{
232	    using SingleRowTileData = Tile<TileType::Vec, T, 1, dstCols, BLayout::RowMajor, -1, -1>;
233	    constexpr int TYPE_COEF = sizeof(float) / sizeof(T);
234	    GlobalData src0Global(src + i * SINGLE_LOOP_ROW * Cols); // ND2ND
235	    GlobalData src1Global(src + i * SINGLE_LOOP_ROW * Cols + SINGLE_LOOP_ROW * Cols);
236	    DstDataGlobalData dst0DataGlobal(out + i * SINGLE_LOOP_ROW * topk);
237	    DstDataGlobalData dst1DataGlobal(out + i * SINGLE_LOOP_ROW * topk + SINGLE_LOOP_ROW * topk);
238	    DstIdxGlobalData dst0IdxGlobal(index + i * SINGLE_LOOP_ROW * topk);
239	    DstIdxGlobalData dst1IdxGlobal(index + i * SINGLE_LOOP_ROW * topk + SINGLE_LOOP_ROW * topk);
240	
241	    ProcessSingleRow<
242	        T, GlobalData, DstDataGlobalData, DstIdxGlobalData, DstTileData, DstDataTileData, DstIndexTileData, SrcTileData,
243	        IndexTileData, SINGLE_LOOP_ROW, dstCols, validCol, topk>(
244	        0, src0Global, dst0DataGlobal, dst0IdxGlobal, sort32DstTile, srcTile, indexTile, mrgDstTile, dTile, iTile,
245	        tmpAddr, EVENT_ID0, (event_t)0);
246	
247	    ProcessSingleRow<
248	        T, GlobalData, DstDataGlobalData, DstIdxGlobalData, DstTileData, DstDataTileData, DstIndexTileData, SrcTileData,
249	        IndexTileData, SINGLE_LOOP_ROW, dstCols, validCol, topk>(
250	        1, src1Global, dst1DataGlobal, dst1IdxGlobal, sort32DstTile, srcTile, indexTile, mrgDstTile, dTile, iTile,
251	        nextTmpAddr, EVENT_ID1, (event_t)1);
252	}
253	
254	template <
255	    typename T, int SINGLE_LOOP_ROW, int validCol, int dstCols, int topk, typename DstTileData, typename SrcTileData,
256	    typename IndexTileData, typename DstDataTileData, typename DstIndexTileData>
257	AICORE inline void InitBuffers(
258	    uint64_t baseAddr, DstTileData sort32DstTile[BUFFER_NUM], DstTileData mrgDstTile[BUFFER_NUM],
259	    SrcTileData srcTile[BUFFER_NUM], IndexTileData& indexTile, DstDataTileData dTile[BUFFER_NUM],
260	    DstIndexTileData iTile[BUFFER_NUM], uint64_t& tmpAddr, uint64_t& nextTmpAddr)
261	{
262	    constexpr uint32_t sort32DstSize = SINGLE_LOOP_ROW * dstCols * sizeof(T) * 2;
263	    constexpr uint32_t srcSize = SINGLE_LOOP_ROW * validCol * sizeof(T) * 2;
264	
265	    TASSIGN(sort32DstTile[0], baseAddr);
266	    TASSIGN(sort32DstTile[1], baseAddr + sort32DstSize / 2);
267	    TASSIGN(mrgDstTile[0], baseAddr + sort32DstSize);
268	    TASSIGN(mrgDstTile[1], baseAddr + sort32DstSize + sort32DstSize / 2);
269	    TASSIGN(indexTile, baseAddr + sort32DstSize * 2);
270	
271	    tmpAddr = baseAddr + sort32DstSize * 2 + validCol * sizeof(uint32_t);
272	    nextTmpAddr = baseAddr + sort32DstSize * 2 + validCol * sizeof(uint32_t) * 3;
273	    uint64_t curAddr = sort32DstSize * 2 + validCol * sizeof(uint32_t) * 5;
274	
275	    TASSIGN(dTile[0], curAddr);
276	    TASSIGN(dTile[1], curAddr + SINGLE_LOOP_ROW * topk * sizeof(T));
277	    TASSIGN(iTile[0], curAddr + SINGLE_LOOP_ROW * topk * sizeof(T) * 2);
278	    TASSIGN(iTile[1], curAddr + SINGLE_LOOP_ROW * topk * sizeof(T) * 2 + SINGLE_LOOP_ROW * topk * sizeof(uint32_t));
279	    TASSIGN(srcTile[0], baseAddr + sort32DstSize * 3 + validCol * sizeof(uint32_t) * 5);
280	    TASSIGN(srcTile[1], baseAddr + sort32DstSize * 3 + validCol * sizeof(uint32_t) * 5 + srcSize / 2);
281	}
282	
283	template <
284	    typename T, int gShape0, int gShape1, int gShape2, int gShape3, int gShape4, int gWholeShape0, int gWholeShape1,
285	    int gWholeShape2, int gWholeShape3, int gWholeShape4, int topk, int blockDim>
286	AICORE inline void runTOPK(__gm__ T* origOut, __gm__ uint32_t* origIndex, __gm__ T* origSrc, __gm__ uint32_t* origInIdx)
287	{
288	    using indexT = uint32_t;
289	    constexpr int validRow = gShape0 * gShape1 * gShape2 * gShape3 / blockDim;
290	    constexpr int validCol = gShape4;
291	    __gm__ T* src = origSrc + get_block_idx() * validRow * gWholeShape4;
292	    __gm__ T* out = origOut + get_block_idx() * validRow * topk;
293	    __gm__ uint32_t* index = origIndex + get_block_idx() * validRow * topk;
294	    __gm__ uint32_t* inIdx = origInIdx;
295	    constexpr int Cols = gWholeShape4;
296	    constexpr int TYPE_COEF = sizeof(float) / sizeof(T);
297	    constexpr int dstCols = validCol * 2 * TYPE_COEF;
298	
299	    using IndexGlobalData =
300	        GlobalTensor<indexT, pto::Shape<1, 1, 1, 1, validCol>, pto::Stride<validCol, validCol, validCol, validCol, 1>>;
301	    IndexGlobalData idxGlobal(inIdx);
302	    using GlobalData = GlobalTensor<
303	        T, pto::Shape<1, 1, 1, SINGLE_LOOP_ROW, validCol>,
304	        pto::Stride<SINGLE_LOOP_ROW * Cols, SINGLE_LOOP_ROW * Cols, SINGLE_LOOP_ROW * Cols, Cols, 1>>;
305	    using DstShapeDim5 = Shape<1, 1, 1, SINGLE_LOOP_ROW, topk>;
306	    using DstStridDim5 = Stride<SINGLE_LOOP_ROW * topk, SINGLE_LOOP_ROW * topk, SINGLE_LOOP_ROW * topk, topk, 1>;
307	    using DstDataGlobalData = GlobalTensor<T, DstShapeDim5, DstStridDim5>;
308	    using DstIdxGlobalData = GlobalTensor<indexT, DstShapeDim5, DstStridDim5>;
309	
310	    using DstTileData = Tile<TileType::Vec, T, SINGLE_LOOP_ROW, dstCols, BLayout::RowMajor, SINGLE_LOOP_ROW, dstCols>;
311	    using SrcTileData = Tile<TileType::Vec, T, SINGLE_LOOP_ROW, validCol, BLayout::RowMajor, SINGLE_LOOP_ROW, validCol>;
312	    using SingleRowTileData = Tile<TileType::Vec, T, 1, dstCols, BLayout::RowMajor, -1, -1>;
313	    using IndexTileData = Tile<TileType::Vec, indexT, 1, validCol, BLayout::RowMajor, 1, validCol>;
314	    using DstDataTileData = Tile<TileType::Vec, T, SINGLE_LOOP_ROW, topk, BLayout::RowMajor, SINGLE_LOOP_ROW, topk>;
315	    using DstIndexTileData =
316	        Tile<TileType::Vec, indexT, SINGLE_LOOP_ROW, topk, BLayout::RowMajor, SINGLE_LOOP_ROW, topk>;
317	    IndexTileData indexTile;
318	    DstTileData sort32DstTile[BUFFER_NUM];
319	    SrcTileData srcTile[BUFFER_NUM];
320	    DstTileData mrgDstTile[BUFFER_NUM];
321	    DstDataTileData dTile[BUFFER_NUM];
322	    DstIndexTileData iTile[BUFFER_NUM];
323	
324	    constexpr uint32_t sort32DstSize = SINGLE_LOOP_ROW * dstCols * sizeof(T) * 2;
325	    uint64_t tmpAddr = 0x0 + sort32DstSize * 2 + validCol * sizeof(indexT);
326	    uint64_t nextTmpAddr = 0x0 + sort32DstSize * 2 + validCol * sizeof(indexT) * 3;
327	    InitBuffers<T, SINGLE_LOOP_ROW, validCol, dstCols, topk>(
328	        0x0, sort32DstTile, mrgDstTile, srcTile, indexTile, dTile, iTile, tmpAddr, nextTmpAddr);
329	
330	    TLOAD(indexTile, idxGlobal);
331	    set_flag(PIPE_V, PIPE_MTE2, EVENT_ID0); // reverse
332	    set_flag(PIPE_V, PIPE_MTE2, EVENT_ID1); // reverse
333	
334	    constexpr uint32_t loopNum = validRow / SINGLE_LOOP_ROW;
335	    for (uint32_t i = 0; i < loopNum; i += 2) {
336	        ProcessIteration<
337	            T, GlobalData, DstDataGlobalData, DstIdxGlobalData, DstTileData, DstDataTileData, DstIndexTileData,
338	            SrcTileData, IndexTileData, dstCols, Cols, validCol, topk>(
339	            out, src, index, i, tmpAddr, nextTmpAddr, sort32DstTile, srcTile, indexTile, mrgDstTile, dTile, iTile);
340	    }
341	    wait_flag(PIPE_V, PIPE_MTE2, EVENT_ID0); // reverse
342	    wait_flag(PIPE_V, PIPE_MTE2, EVENT_ID1); // reverse
343	}
344	
345	template <
346	    typename T, int gShape0, int gShape1, int gShape2, int gShape3, int gShape4, int gWholeShape0, int gWholeShape1,
347	    int gWholeShape2, int gWholeShape3, int gWholeShape4, int topk, int blockDim>
348	__global__ AICORE void Topk(__gm__ uint8_t* out, __gm__ uint8_t* index, __gm__ uint8_t* src, __gm__ uint8_t* inIdx)
349	{
350	    using indexT = uint32_t;
351	    Check<
352	        half, gShape0, gShape1, gShape2, gShape3, gShape4, gWholeShape0, gWholeShape1, gWholeShape2, gWholeShape3,
353	        gWholeShape4, topk, blockDim>();
354	    if constexpr (std::is_same_v<T, uint16_t>) {
355	        runTOPK<
356	            half, gShape0, gShape1, gShape2, gShape3, gShape4, gWholeShape0, gWholeShape1, gWholeShape2, gWholeShape3,
357	            gWholeShape4, topk, blockDim>(
358	            reinterpret_cast<__gm__ half*>(out), reinterpret_cast<__gm__ indexT*>(index),
359	            reinterpret_cast<__gm__ half*>(src), reinterpret_cast<__gm__ indexT*>(inIdx));
360	    } else {
361	        runTOPK<
362	            float, gShape0, gShape1, gShape2, gShape3, gShape4, gWholeShape0, gWholeShape1, gWholeShape2, gWholeShape3,
363	            gWholeShape4, topk, blockDim>(
364	            reinterpret_cast<__gm__ float*>(out), reinterpret_cast<__gm__ indexT*>(index),
365	            reinterpret_cast<__gm__ float*>(src), reinterpret_cast<__gm__ indexT*>(inIdx));
366	    }
367	}
368	
369	#ifndef __COSTMODEL
370	template <typename T>
371	void launchTopk(uint8_t* out, uint8_t* index, uint8_t* src, uint8_t* inIdx, void* stream)
372	{
373	    constexpr int blockDim = 48;
374	    constexpr int gShape3 = 4800;
375	    constexpr int gShape4 = 1024;
376	    constexpr int gWholeShape3 = 4800;
377	    constexpr int gWholeShape4 = 1280;
378	    constexpr int topk = 1000;
379	    Topk<T, 1, 1, 1, gShape3, gShape4, 1, 1, 1, gWholeShape3, gWholeShape4, topk, blockDim>
380	        <<<blockDim, nullptr, stream>>>(out, index, src, inIdx);
381	}
382	
383	template void launchTopk<float>(uint8_t* out, uint8_t* index, uint8_t* src, uint8_t* inIdx, void* stream);
384	#endif
