            if (ReachExhausted(i0, i1, i2, i3, s0Structs, s1Structs, s2Structs, s3Structs, listNum)) {
                break;
            }
        }
    }

    WriteExhausted(i0, i1, i2, i3, mrgSortList0, mrgSortList1, mrgSortList2, mrgSortList3);
}

